#pragma once
static const char camera_page[] =
    "<!doctype html>\n"
    "<html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
    "<title>EdgeZ Camera</title><style>\n"
    ":root{font-family:system-ui,sans-serif;color:#17352c;background:#eff3ee}*{box-sizing:border-box}body{margin:0;padding:36px 20px}main{max-width:850px;margin:auto}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:36px}header b{letter-spacing:.12em;font-size:14px}small{color:#577267}.tag{font-size:12px;border:1px solid #b7c9bf;border-radius:30px;padding:7px 12px}h1{font-size:clamp(32px,6vw,52px);letter-spacing:-.045em;margin:0 0 12px}p{color:#577267;line-height:1.5}.toolbar{display:flex;gap:14px;align-items:center;margin:24px 0}button,.download{border:0;border-radius:12px;padding:14px 22px;font:600 15px system-ui;background:#1e6849;color:white;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.download{background:transparent;color:#1e6849;text-decoration:none}section{border:1px solid #d6e0d7;background:#fff;border-radius:20px;padding:22px;box-shadow:0 12px 32px #1a372908}#frame{min-height:280px;display:grid;place-items:center;border-radius:12px;background:#f5f7f3;overflow:hidden}#frame span{text-align:center;color:#738778;padding:40px}img{display:block;max-width:100%;height:auto}progress{width:100%;height:8px;accent-color:#1e6849;margin:20px 0 12px}#status{font-size:14px;margin:0;min-height:22px}.meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-top:18px}footer{font-size:12px;color:#738778;margin-top:22px}a[hidden],img[hidden],span[hidden]{display:none}\n"
    "</style><main><header><b>EDGEZ / CAMERA</b><span class=\"tag\">HaLow remote capture</span></header>\n"
    "<h1>A view from out there.</h1><p>Wake the remote LED, or take a photo and bring it here.</p>\n"
    "<div class=\"toolbar\"><button id=\"led\">Wake LED</button><button id=\"capture\">Take photo</button><a id=\"download\" class=\"download\" hidden download=\"edgez-photo.jpg\">Save photo</a></div>\n"
    "<section><div id=\"frame\"><span id=\"empty\">Your next photo will appear here.</span><img id=\"photo\" alt=\"Photo from the remote camera\" hidden></div>\n"
    "<progress id=\"progress\" value=\"0\" max=\"100\"></progress><p id=\"status\" role=\"status\" aria-live=\"polite\">Connecting to camera gateway\u2026</p>\n"
    "<div class=\"meta\"><small id=\"connection\">Checking remote camera</small><small id=\"detail\"></small></div></section>\n"
    "<footer>Stay connected to EdgeZ-Camera Wi-Fi while capturing.</footer></main>\n"
    "<script>\n"
    "const $=id=>document.getElementById(id);let shown=0,loading=false,objectURL='';\n"
    "async function update(){\n"
    " try{\n"
    "  const response=await fetch('/api/status',{cache:'no-store'});if(!response.ok)throw Error('Gateway unavailable');\n"
    "  const s=await response.json();$('connection').textContent=s.peer?'Remote camera found':'Waiting for remote camera';\n"
    "  $('capture').disabled=s.busy;$('led').disabled=s.busy; $('progress').value=s.total?100*s.received/s.total:0;\n"
    "  const messages={idle:'Ready when you are.',waking:'Waking remote LED\u2026','led-complete':'LED acknowledged \u2014 on for five seconds.',queued:'Starting capture\u2026',discovering:'Finding the remote camera\u2026',capturing:'Waking camera and taking photo\u2026',receiving:'Receiving photo\u2026',finishing:'Checking photo\u2026',complete:'Photo ready.',error:s.error};\n"
    "  $('status').textContent=messages[s.state]||s.state;\n"
    "  $('detail').textContent=s.total?`${Math.round(s.received/1024)} / ${Math.round(s.total/1024)} KB \u00b7 ${s.retries} retries`:'';\n"
    "  if(s.state==='complete'&&s.id!==shown&&!loading){\n"
    "   loading=true;\n"
    "   try{const image=await fetch('/photo.jpg?id='+s.id,{cache:'no-store'});if(!image.ok)throw Error('Photo unavailable');\n"
    "    const blob=await image.blob();const next=URL.createObjectURL(blob);$('photo').src=next;$('photo').hidden=false;$('empty').hidden=true;\n"
    "    $('download').href=next;$('download').hidden=false;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=next;shown=s.id;\n"
    "   }finally{loading=false;}\n"
    "  }\n"
    " }catch(e){$('status').textContent=e.message+' \u2014 stay connected to gateway Wi-Fi.';}\n"
    " finally{setTimeout(update,600);}\n"
    "}\n"
    "async function requestAction(endpoint){$('capture').disabled=true;$('led').disabled=true;try{const r=await fetch(endpoint,{method:'POST'});if(!r.ok){const e=await r.json();throw Error(e.error||'Action could not start');}}catch(e){$('status').textContent=e.message;$('capture').disabled=false;$('led').disabled=false;}}\n"
    "$('capture').onclick=()=>requestAction('/api/capture');\n"
    "$('led').onclick=()=>requestAction('/api/led');\n"
    "update();\n"
    "</script></html>\n"
;
